package org.cgse.core;
import java.util.*;import java.nio.file.*;import java.math.BigInteger;import com.google.gson.*;
public class AdmissionProbe {public static void main(String[]args)throws Exception{var path=Path.of(args[0]);var manual=MixedSweep.read(path.resolve("manual.json"));var config=JsonParser.parseString(Files.readString(Path.of(args[1]))).getAsJsonObject();var compiler=MixedSweep.compiler(manual,manual,"manual",73);var out=new JsonArray();for(var element:config.getAsJsonArray("requests")){var r=element.getAsJsonObject();var target=r.get("target").getAsString();var budget=new PlanningBudget(0,20_000_000,128L<<20,()->false,System::nanoTime);GraphCompiler.Compiled<String> graph;try(var compilation=compiler.begin(target,Map.of(),Set.of(),budget)){while(!compilation.step()){}graph=compilation.result();}try(var solve=new GraphSolve<>(graph,target,r.get("amount").getAsLong(),manual.stock(),manual.external(),Map.of(),true,true,budget,System.nanoTime(),new CatalystPolicy(4096,64),manual.stock())){while(!solve.step()){}var candidate=solve.result();var row=r.deepCopy();row.addProperty("result",candidate.result().name());row.addProperty("recipes",graph.recipes().size());row.addProperty("selected",graph.selected().size());int ambiguous=0,productive=0;long alt=0;for(var entry:graph.selected().entrySet()){var sources=compiler.producers(entry.getKey());if(sources.size()>1){ambiguous++;alt+=sources.size()-1;}int add=0;for(var recipe:sources)if(recipe.executionOutputs().getOrDefault(entry.getKey(),0L)>recipe.inputs().getOrDefault(entry.getKey(),0L))add++;if(add>1)productive++;}row.addProperty("ambiguous",ambiguous);row.addProperty("productive_ambiguity",productive);row.addProperty("alternative_sum",alt);var deficits=new JsonObject();for(var key:candidate.missingExact().keySet())deficits.addProperty(key,compiler.producers(key).size());row.add("deficit_sources",deficits);out.add(row);System.out.println(r.get("id")+" "+candidate.result()+" selected="+graph.selected().size()+" ambiguity="+ambiguous+" productive="+productive+" alternatives="+alt);}}
Files.writeString(Path.of(args[2]),new Gson().toJson(out));}}
